import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Sovereign OS Roadmap","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/ROADMAP.md"},"headers":[],"relativePath":"sovereign-os/roadmap.md","filePath":"sovereign-os/roadmap.md"}'),n={name:"sovereign-os/roadmap.md"};function r(s,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="sovereign-os-roadmap" tabindex="-1">Sovereign OS Roadmap <a class="header-anchor" href="#sovereign-os-roadmap" aria-label="Permalink to &quot;Sovereign OS Roadmap&quot;">​</a></h1><h2 id="status-legend" tabindex="-1">Status Legend <a class="header-anchor" href="#status-legend" aria-label="Permalink to &quot;Status Legend&quot;">​</a></h2><ul><li>✅ Complete — implemented and qualified on supported hardware</li><li>🟡 In progress — implementation or hardware qualification is active</li><li>⚪ Planned — accepted direction, not yet started</li><li>⏳ Pending decision — research or an RFC must close the design boundary</li></ul><h2 id="current-position" tabindex="-1">Current Position <a class="header-anchor" href="#current-position" aria-label="Permalink to &quot;Current Position&quot;">​</a></h2><p>✅ Phase 01 — Flashable Raspberry Pi Image POC</p><p>The Raspberry Pi 5 image build, flash, first-boot, Pi-hole, persistent DATA partition, local routing, first-login, and Sovereign Console health experience have been exercised on physical hardware.</p><p>✅ Milestone 01.1 — Appliance Update Foundation</p><p>The signed appliance updater can inspect, prepare, back up, stage, activate, health-check, commit, recover, and roll back versioned releases while preserving the dedicated DATA partition. An initial signed update transaction passed Raspberry Pi qualification.</p><p>The first fully versioned appliance-release qualification, from preview.9 to preview.10, exposed service-readiness and systemd dependency races. Automatic rollback worked and restored preview.9. The fixes were qualified on Raspberry Pi 5 hardware in a clean preview.11 base to preview.12 update campaign: an interrupted-at-<code>validating</code> recovery, a forced target-health rollback, and a successful activation all held with reboot persistence and no regression to Console, DNS, Pi-hole, Nginx, SSH, credentials, or the dedicated DATA partition. See the <a href="./docs/research/preview-12-appliance-update-qualification-report.html">preview.12 appliance update qualification report</a>.</p><p>Persistent-data restore, bounded retention (<code>prune</code>), and signed trust rotation (<code>rotate-trust</code>) are all implemented and hardware-qualified on Raspberry Pi 5, most recently against a real <code>0.1.0-preview.13</code> base image built and flashed with all three shipped in for the first time — see the <a href="./docs/research/preview-14-appliance-update-qualification-report.html">preview.14 appliance update qualification report</a> and the <a href="./docs/research/prune-and-rotate-trust-hardware-qualification-report.html">prune and trust rotation hardware qualification report</a>. Production signing-key custody is decided (ADR-0006), and the production key (<code>sovereign-production-1</code>) is now generated, provisioned into the image-builder trust store, and proven end-to-end: <code>v0.1.0-preview.17</code> is a real production-signed release that has been built, published, discovered, installed, and restored from on Raspberry Pi 5 hardware — see the <a href="./docs/research/first-production-signed-release-qualification-report.html">first production-signed release</a>, <a href="./docs/research/first-production-signed-release-install-qualification-report.html">install</a>, and <a href="./docs/research/production-signed-restore-qualification-report.html">restore</a> qualification reports. <code>prune</code> and <code>rotate-trust</code> have since each been exercised as part of a real signed-release install cycle — <code>prune</code> against <code>v0.1.0-preview.23</code>, and <code>rotate-trust</code> with the real production key against the device&#39;s real trust store on 2026-08-09 — see the <a href="./docs/research/rotate-trust-real-signed-cycle-qualification-report.html">rotate-trust real signed-cycle qualification report</a>. <a href="./docs/rfcs/0014-appliance-update-system.html">RFC-0014</a> is formally Accepted. See Milestone 2 below for the full closing summary.</p><p>Unattended automatic installation remains disabled until the manual, health-gated update path and its operational controls are qualified.</p><h2 id="milestone-sequence" tabindex="-1">Milestone Sequence <a class="header-anchor" href="#milestone-sequence" aria-label="Permalink to &quot;Milestone Sequence&quot;">​</a></h2><h3 id="_1-complete-appliance-update-qualification" tabindex="-1">1. Complete Appliance Update Qualification <a class="header-anchor" href="#_1-complete-appliance-update-qualification" aria-label="Permalink to &quot;1. Complete Appliance Update Qualification&quot;">​</a></h3><p><strong>Status:</strong> ✅ Complete</p><p><strong>User outcome:</strong> Install a compatible Sovereign appliance release without reflashing or losing persistent data.</p><p>Qualification pair:</p><ul><li>preview.11: clean flashable base containing the systemd and readiness fixes;</li><li>preview.12: signed, versioned installed-device update built from the same source revision.</li></ul><p>The physical qualification on Raspberry Pi 5 proved:</p><ul><li>update compatibility and signature verification;</li><li>staging without changing the active release;</li><li>interruption recovery (interrupted at <code>validating</code>, automatic boot-time restore of preview.11);</li><li>forced health-check failure and automatic rollback;</li><li>successful activation and commit;</li><li>reboot persistence;</li><li>preservation of Pi-hole configuration, credentials, update state, and the dedicated DATA mount; and</li><li>no regression to Console, DNS, Pi-hole, Nginx, or SSH.</li></ul><p>See the <a href="./docs/research/preview-12-appliance-update-qualification-report.html">preview.12 appliance update qualification report</a> for full evidence.</p><h3 id="_2-production-update-operations" tabindex="-1">2. Production Update Operations <a class="header-anchor" href="#_2-production-update-operations" aria-label="Permalink to &quot;2. Production Update Operations&quot;">​</a></h3><p><strong>Status:</strong> ✅ Complete — every item below is implemented and hardware-qualified, including the three gaps that were still open as of early 2026-08-09: <code>restore</code>-into-rollback wiring is recorded as a deliberate deferral rather than left ambiguous (nothing in the update pipeline touches persistent data yet, so there is nothing for it to protect against), a genuine unattended <code>prune</code> timer fire was observed, and <code>rotate-trust</code> has now been exercised with the real production key against the real device trust store. <a href="./docs/rfcs/0014-appliance-update-system.html">RFC-0014</a> is formally Accepted, closing the last procedural gap (its Acceptance Criteria and Decision sections had lagged behind its own implementation, which raced ahead of the paperwork).</p><p><strong>Depends on:</strong> Completed preview.11 to preview.12 qualification</p><p><strong>User outcome:</strong> A supportable update mechanism with trustworthy release and recovery operations.</p><p>Planned work:</p><ul><li>automate persistent-data restore verification — <code>sovereign-update restore</code> is implemented and hardware-qualified against real Pi-hole state on Raspberry Pi 5, including a forced-health-failure rollback path, twice now: once manually deployed, and again on a real <code>preview.13</code> base image that shipped it natively (see <a href="./update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a> and the <a href="./docs/research/restore-hardware-qualification-report.html">restore</a> and <a href="./docs/research/preview-14-appliance-update-qualification-report.html">preview.14</a> qualification reports); it still has not shipped through a release used by anyone beyond qualification. Wiring it into automatic update rollback is deliberately deferred, not open work: <code>activate_release</code>&#39;s rollback path doesn&#39;t touch persistent data today because nothing in <code>prepare</code>/<code>stage</code>/<code>activate</code> does, so there is nothing yet for an automatic restore to undo. See the <a href="./docs/research/restore-rollback-wiring-deferral.html">restore-rollback wiring deferral</a> decision note — this becomes straightforward once an actual persistent-data migration step exists to protect against;</li><li>define bounded retention and cleanup for old releases, backups, journals, and failed transactions — <code>sovereign-update prune [--dry-run]</code> is implemented and hardware-qualified on Raspberry Pi 5 against real backups, releases, and transaction journals, including confirming the live device stays healthy through an aggressive real deletion pass (see <a href="./update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a> and the <a href="./docs/research/prune-and-rotate-trust-hardware-qualification-report.html">prune and trust rotation qualification report</a>). Now wired into a daily <code>sovereign-update-prune.timer</code> (jittered, catches up on boot if a run was missed), hardware-verified running under its own hardened sandbox on Raspberry Pi 5; not yet shipped through a release beyond qualification. A genuine unattended timer-elapsed run — via the boot catch-up path, after the device missed its overnight window — was observed on 2026-08-09, closing the one remaining gap here: see the <a href="./docs/research/prune-timer-unattended-fire-qualification-report.html">prune timer unattended-fire qualification report</a>;</li><li>establish production signing-key custody, rotation, and revocation — decided in <a href="./docs/adrs/0006-production-signing-key-custody.html">ADR-0006</a> (password-manager-held key, hardware key as a future upgrade). Routine rotation/revocation is implemented as <code>sovereign-update rotate-trust</code> (signed, atomic, refuses any change that would leave a channel with no trusted key — see <a href="./update/README.html">update/README.md</a>&#39;s &quot;Trust Rotation v1&quot; section) and hardware-qualified on Raspberry Pi 5, including the realistic single-key rotation handoff, immediate enforcement of revocation, and the lockout protection (see the <a href="./docs/research/prune-and-rotate-trust-hardware-qualification-report.html">prune and trust rotation qualification report</a>). The production key (<code>sovereign-production-1</code>, Ed25519, scoped to both <code>preview</code> and <code>stable</code>) has now been generated under that custody decision and its public half is baked into the image-builder overlay&#39;s trust store, so future base images trust it out of the box; the private half lives only as an encrypted secret in the maintainer&#39;s password manager. <code>v0.1.0-preview.17</code> is the first release signed with it, published, discovered, and — as of a full <code>prepare</code>/<code>backup</code>/<code>stage</code>/ <code>activate</code> run on the same Raspberry Pi 5 — genuinely <strong>installed</strong>: the device now runs <code>0.1.0-preview.17</code>, <code>update_state: committed</code>, confirmed across a cold reboot. See the <a href="./docs/research/first-production-signed-release-qualification-report.html">discovery</a> and <a href="./docs/research/first-production-signed-release-install-qualification-report.html">install</a> qualification reports. That install campaign also found and fixed a real regression: <code>sovereign-proof.service</code> failing on any boot after <code>prune</code> removes the base image&#39;s own (now-inactive) release directory — <code>proof-init</code> now only performs that check during first-boot bootstrap. <code>restore</code> has since also been qualified against the real pre-activation backup that install created: correctly rejected a version-mismatched restore by default, then recovered an injected canary correctly under <code>--force</code> with no regression — see the <a href="./docs/research/production-signed-restore-qualification-report.html">production-signed restore qualification report</a>. <code>prune</code> has now been exercised as part of a genuine signed-release install cycle: <code>v0.1.0-preview.23</code>, signed with the real production key by its custody holder (the assistant never handles that key, per ADR-0006), discovered, installed, and committed on the qualification device, followed by a real (non-dry-run) <code>prune</code> run. It correctly removed nothing — not a gap, but confirmation that <code>prune_releases</code>&#39; protection logic works as designed: a release beyond the raw <code>keep_count</code> (here, <code>0.1.0-preview.21</code>, a third release against <code>keep_count: 2</code>) stays protected as long as any transaction still within retention (<code>committed</code> state, <code>keep_days: 90</code>) records it as a rollback anchor — a genuinely useful, real-cycle confirmation that release and transaction retention interlock correctly rather than pruning something a still-live rollback path depends on. <code>rotate-trust</code> has now also been exercised with the real production key against the real device trust store, while the device ran a real signed, already-committed release (<code>0.1.0-proof.3</code>): a real, maintainer-signed add-only manifest brought the trust store to genuine dual trust, the newly added key proved itself functional by signing its own revocation, and a negative test confirmed revocation is enforced immediately against the real production key&#39;s rotation channel — see the <a href="./docs/research/rotate-trust-real-signed-cycle-qualification-report.html">rotate-trust real signed-cycle qualification report</a>. This closes the last named gap in this milestone. Getting a rotation manifest onto already-flashed devices without an operator manually running the command still depends on the Update Discovery work in item 3 below (now complete, so this is unblocked whenever a rotation is actually needed);</li><li>approve the update RFC and production manifest policy — the production manifest policy has been live and deployed since early qualification (<code>/etc/sovereign/update-policy.json</code>); <a href="./docs/rfcs/0014-appliance-update-system.html">RFC-0014</a> itself was formally Accepted on 2026-08-09, after its Acceptance Criteria and Decision sections were brought in line with the implementation and hardware qualification that had already shipped around it;</li><li>publish release compatibility, rollback limitations, and recovery guidance — published as <a href="./docs/operations/update-recovery-and-compatibility.html">docs/operations/update-recovery-and-compatibility.md</a>, written for the device operator rather than a contributor; and</li><li>qualify every supported source-to-target update path on real hardware. A <code>0.1.0-preview.17</code> → <code>0.1.0-preview.18</code> attempt surfaced a real structural gap: the installed updater&#39;s appliance file allowlist was fixed at flash time and couldn&#39;t learn about a new file added by the release introducing it. Fixed and hardware-qualified the same day — the validator now rejects only missing required files, not unrecognized ones, and classifies appliance scripts by shebang instead of a hardcoded name set; the exact real stuck transaction was recovered through to <code>committed</code> on real hardware, confirmed persistent across a reboot — see <a href="./docs/research/appliance-file-set-update-ceiling-finding.html">the finding</a> and its <a href="./docs/research/appliance-file-set-ceiling-fix-qualification-report.html">fix qualification report</a>. This does not touch the larger, still-unresolved question of delivering new systemd units/base-image content via update at all (see item 6 below) — only the narrower file-allowlist symptom.</li></ul><h3 id="_3-update-discovery-and-console-controls" tabindex="-1">3. Update Discovery and Console Controls <a class="header-anchor" href="#_3-update-discovery-and-console-controls" aria-label="Permalink to &quot;3. Update Discovery and Console Controls&quot;">​</a></h3><p><strong>Status:</strong> ✅ Complete</p><p><strong>Depends on:</strong> Production Update Operations for the Console-facing and installation-triggering bullets below; the device-side check-and-notify bullet was deliberately scoped in RFC-0015 to not depend on it (no Console change, no production key) and has already started.</p><p><strong>User outcome:</strong> Learn about and install <code>x+1</code> from Sovereign Console without using the command line or reflashing.</p><p>Planned work:</p><ul><li>publish signed update-channel metadata over HTTPS, and periodically check for compatible updates without sending household data — accepted in <a href="./docs/rfcs/0015-update-discovery.html">RFC-0015</a> and implemented as <code>sovereign-update check</code>, reusing the existing signed-manifest verification unchanged, with no new trust logic, no Console change, and no production key required. Runs daily via <code>sovereign-update-check.timer</code>, hardware-verified on Raspberry Pi 5 against the real live GitHub API, including the positive &quot;update found&quot; path against a genuinely published (non-draft) release — see <a href="./update/README.html">update/README.md</a>&#39;s &quot;Update Discovery v1&quot; section and the <a href="./docs/research/update-discovery-positive-path-qualification-report.html">positive-path qualification report</a>. That campaign also surfaced a real gap, now fixed: <code>build-image.yml</code>&#39;s release-publish step never uploaded the update-candidate manifest/bundle at all, and its filename collided with the image&#39;s own provenance file (now <code>image-manifest.json</code>). The workflow now conditionally uploads the unsigned update-candidate assets when <code>build_update_candidate</code> is selected; an operator still has to sign and upload the <code>.sig</code> offline before a release becomes discoverable;</li><li><strong>Console authentication</strong> — the prerequisite ADR-0005 itself named before any mutating Console action can exist. Decided and implemented in <a href="./docs/adrs/0007-console-authentication.html">ADR-0007</a>: a separate Console-specific credential (<code>sovereign-console-password</code>), a loopback-only, systemd-hardened login backend (<code>sovereign-console-auth</code>, <code>/api/v1/auth/*</code>), session cookies with CSRF protection, and per-source rate limiting without lockout, with a sign-in UI wired into Console&#39;s topbar. Unit-tested (<code>tests/test_console_auth.py</code>) and hardware-qualified on Raspberry Pi 5 — see the <a href="./docs/research/console-authentication-hardware-qualification-report.html">console authentication hardware qualification report</a>. A real signed-release install attempt (<code>v0.1.0-preview.18</code>) surfaced a structural finding bigger than Console auth itself — see <a href="./docs/research/appliance-file-set-update-ceiling-finding.html">the finding</a> — since fixed: <code>.18</code> is genuinely installed via a real update on real hardware, <code>console-auth</code>&#39;s binary included. The base-image content it also needs (systemd unit, <code>sysusers.d</code> group, directory bootstrap) was then deployed manually and permanently to the qualification device — real, accepted drift against what any future image build produces until the next reflash, not something an update can deliver (tracked at item 6 below). Console authentication is now genuinely live and working on real hardware;</li><li><strong>the first Console-triggered privileged action</strong> — decided and implemented in <a href="./docs/adrs/0008-console-privileged-action-invocation.html">ADR-0008</a>: a file-existence trigger picked up by a <code>systemd</code> path-activated, root-owned oneshot runner, scoped to exactly one action, <code>sovereign-update check</code>. Hardware-qualified on Raspberry Pi 5 — the full chain (auth/CSRF gating, the trigger actually firing, a real check running as root, the result surfacing back to Console, cooldown enforcement) verified correctly, after finding and fixing two real defects (a missing <code>ReadWritePaths=</code> grant, and a static-group name that collided with an unrelated service&#39;s own <code>DynamicUser</code> identity) — see the <a href="./docs/research/console-check-trigger-hardware-qualification-report.html">qualification report</a>. <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code> (an actual install trigger) are explicitly out of scope for this pass — deliberately smaller blast radius first;</li><li><strong>user-triggered download and installation, with full state reporting</strong> — decided and implemented in <a href="./docs/adrs/0009-console-triggered-install.html">ADR-0009</a>: reuses ADR-0008&#39;s file-trigger mechanism, resolved for a real action&#39;s parameter/blast-radius/status needs by having the privileged side independently re-decide the target through the same trust-anchored discovery <code>check</code> already uses (Console never supplies or influences which version installs), a required fresh password re-entry, and a single continuous prepare→backup→stage→activate sequence with no per-step Console confirmation. Hardware-qualified on Raspberry Pi 5 — the full sequence committed and survived a reboot via the real Console web API, after finding and fixing five real, previously-unexercised defects (a missing and then insufficient health-check retry budget, two missing systemd capabilities <code>nginx -t</code>&#39;s real startup side effects need, an unretried local-access race against service restart, and a release directory silently losing world-traversability under the trigger unit&#39;s own umask hardening) — see the <a href="./docs/research/console-triggered-install-qualification-report.html">qualification report</a>;</li><li>show version, channel, release notes, download size, reboot requirements, and rollback limitations in Console — done: the update panel now shows a details row (channel, download size, reboot requirement, rollback support/limitations, release-notes link) whenever an update is available, sourced from fields <code>sovereign-update check</code> already verified from the signed manifest but hadn&#39;t previously surfaced past the CLI;</li><li>retain a CLI recovery path independent of Console (already true: every step ADR-0009 orchestrates — <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code>/ <code>recover</code>/<code>discard</code> — remains directly callable, unattended installs are simply the same primitives run in sequence).</li></ul><p>The initial policy is <strong>notify and require approval</strong>. Automatic download and maintenance-window installation follow only after repeated field qualification. Every automatic policy retains signature verification, health-gated activation, and automatic rollback.</p><h3 id="_4-local-conversation-and-capabilities" tabindex="-1">4. Local Conversation and Capabilities <a class="header-anchor" href="#_4-local-conversation-and-capabilities" aria-label="Permalink to &quot;4. Local Conversation and Capabilities&quot;">​</a></h3><p><strong>Status:</strong> ✅ Complete — started 2026-08-09. Every capability (<code>system.health</code>, Pi-hole, <code>web.search</code>/<code>web.fetch</code>) is implemented, Console-wired, and hardware-qualified, including the real signed-release pass (2026-08-22/23) that closes PR #17&#39;s last open checklist item — see <a href="./docs/research/searxng-and-llamacpp-signed-release-hardware-qualification-report.html">searxng-and-llamacpp-signed-release-hardware-qualification-report.md</a>.</p><p><strong>RFCs:</strong> All four of the milestone&#39;s required RFCs are Accepted — <a href="./docs/rfcs/0002-local-conversation-and-inference-runtime.html">RFC-0002</a> (runtime and conversation architecture), <a href="./docs/rfcs/0003-capability-contract.html">RFC-0003</a> (the typed registry and six-stage deterministic executor), <a href="./docs/rfcs/0004-ai-capability-invocation.html">RFC-0004</a> (AI capability invocation, including the untrusted-forever boundary on capability results), and <a href="./docs/rfcs/0006-pihole-capability-mapping.html">RFC-0006</a> (Pi-hole capability mapping, aggregate-only per Console health&#39;s own privacy precedent).</p><p><strong>Capabilities:</strong> <code>system.health</code>, <code>pihole.status</code>, and <code>pihole.summary</code> are all implemented (<code>sovereign_capabilities.py</code>, <code>sovereign_pihole.py</code>, <code>sovereign_system.py</code>) and smoke-tested against the real device — see the <a href="./docs/research/pihole-capabilities-smoke-test-report.html">pihole</a> and <a href="./docs/research/system-health-capability-smoke-test-report.html">system.health</a> reports. <code>web.search</code> and <code>web.fetch</code> are now implemented too (<code>sovereign_websearch.py</code>), against <a href="./docs/rfcs/0017-web-search-and-fetch-capability-mapping.html">RFC-0017</a> (Accepted 2026-08-21 — implemented and hardware-qualified ahead of formal acceptance, matching this project&#39;s own precedent, e.g. the Conversation Service itself shipped against RFC-0002/0003/0004 before those RFCs&#39; Decision sections were filled in). Both are backed by the now-embedded SearXNG service: <code>image-builder/sovereign/searxng-image.env</code> (real pinned ARM64 digest, <code>ghcr.io/searxng/searxng</code>) and <code>appliance/searxng/</code> (compose template, <code>settings.yml</code>, <code>start-searxng</code>/<code>stop-searxng</code>, the same artifact/import/server three-stage systemd shape Pi-hole and llama.cpp use), unit-tested (<code>tests/test_searxng_deployment.py</code>) — see <a href="./docs/research/searxng-deployment-assessment.html">searxng-deployment-assessment.md</a>&#39;s Addendum for the real-image verification (pinned digest, confirmed <code>SEARXNG_SECRET</code> env-var mechanism, no built-in healthcheck, real JSON response shape) this embedding was built from.</p><p><code>sovereign_conversation.py</code> gained the real confirmation pause/resume flow RFC-0004 specified but left unimplemented (<code>PendingTurnStore</code>, <code>resume_turn()</code>, building on <code>sovereign_capabilities.ConfirmationStore</code>&#39;s already-implemented, already-tested <code>issue()</code>/<code>consume()</code>) — a <code>required</code>-confirmation proposal now halts its round and returns a <code>pending_confirmation</code> object with the literal disclosed arguments, resumed via <code>POST /message</code>&#39;s new <code>confirmation: {token, approve}</code> field, single-use and audited either way. <code>web.fetch</code>&#39;s SSRF policy resolves the destination address immediately before connecting (not a one-time hostname check a later DNS lookup could bypass) and pins the TCP connection to that validated address while preserving the original hostname for TLS SNI/certificate checks — verified live against real public HTTPS sites and against every one of this device&#39;s own real loopback ports during this session. <code>web.search</code> was verified live against a real SearXNG container too (real query, real trimmed results). <code>/data/sovereign/capabilities/policy.json</code>&#39;s <code>external_enabled</code> gate is read fresh per request and fails safe to disabled when the file doesn&#39;t exist — reusing the same directory <code>sovereign-conversation.service</code> was already granted write access to for its audit log, rather than a new top-level file that would have needed its own systemd hardening grant (and a root-run bootstrap step this project has no existing mechanism for, having no <code>tmpfiles.d</code> usage anywhere — checked before implementing, not after). 30 new tests (<code>tests/test_websearch_capabilities.py</code>) plus extensions to <code>tests/test_conversation.py</code>/<code>test_conversation_service.py</code> (full HTTP-level pause/resume/policy round trips against the real registry).</p><p>Console&#39;s Chat page now renders the approve/deny confirmation prompt too: a <code>.confirmation-card</code> discloses the literal capability name and arguments from <code>pending_confirmation</code>, resumes the turn via the <code>confirmation</code> request field on Approve/Deny, locks the composer while a decision is pending, and clears itself on sign-out — unit-tested (<code>tests/test_console.py</code>) and manually verified end-to-end against a stub backend. Fixed a real pre-existing UI bug in the process: chat receipts previously always said &quot;stayed local&quot; regardless of classification, which would have been actively wrong for these two capabilities.</p><p>The settings toggle is done too: authenticated <code>GET</code>/ <code>POST /api/v1/conversation/policy</code> (atomic <code>.tmp</code>-then-rename write, same convention <code>sovereign-pihole-password</code> uses) and a labeled switch on Chat (<code>#chat-policy-row</code>) that loads the real state on sign-in and persists a change immediately, reverting the visible toggle if the write fails. Manually verified end-to-end: toggling on and back off against a stub backend correctly gated whether a search proposal reached a confirmation prompt at all. <code>web_search_enabled</code> still defaults to <code>false</code> on a device that has never touched the toggle.</p><p><strong>Real-hardware qualification is done</strong> — see the <a href="./docs/research/web-search-and-confirmation-flow-hardware-qualification-report.html">web.search/confirmation flow hardware qualification report</a>: real pinned digests pulled and run natively on the project&#39;s Raspberry Pi 5 (<code>sovereign.local</code>, still <code>0.1.0-proof.3</code>, the same device the llama-server deployment was qualified against), a real 2GB model download with a matching checksum, real inference, real SearXNG search, all five capabilities exercised through the real executor including a real SSRF test against the device&#39;s own actual running services, a real confirmation round trip, and a real browser-authenticated pass driven by the project owner (their Console password never seen by the assistant, matching this project&#39;s standing credential-handling convention). Found and fixed one real bug live: the policy toggle&#39;s <code>GET</code> request was missing its CSRF header and always failed against the real server (the <code>POST</code> path was unaffected) — a regression test now covers it. This was a manual smoke-test deployment, the same precedent the original llama-server qualification established, not a real signed release. The real signed-release pass, including <code>sovereign-conversation.service</code>&#39;s real <code>DynamicUser</code> sandbox and the directory-creation question this report&#39;s own Limitations left open, is done — see the <a href="./docs/research/searxng-and-llamacpp-signed-release-hardware-qualification-report.html">signed-release qualification report</a>.</p><p><strong>Release tooling is now wired for SearXNG — and a pre-existing llama.cpp gap it surfaced is fixed too.</strong> <code>scripts/create-release-bundle.py</code> and <code>create-update-release.py</code> now handle SearXNG&#39;s env/OCI-tar/manifest component the same way they already handle Pi-hole and llama.cpp. Investigating this surfaced a real, pre-existing defect (see the <a href="./docs/research/searxng-signed-release-qualification-assessment.html">signed-release qualification assessment</a>): the installed <code>sovereign-update</code>&#39;s manifest-schema validation and <code>activate_release</code> were still Pi-hole-only and hardcoded, so any real release manifest <code>create-update-release.py</code> has produced since llama.cpp was added (with a <code>components.llama</code> key) would have been rejected outright by the installed updater, and llama&#39;s own OCI image was never actually <code>docker load</code>ed on activation. Both are now a single data-driven <code>IMAGE_COMPONENTS</code> loop covering all three images uniformly (<code>RELEASE_FILES</code>, the manifest JSON Schema, <code>validate_release_payload</code>, <code>activate_release</code>), with the full update test suite (519 tests) updated and passing.</p><p><strong>Real signed-release qualification is done (2026-08-22/23).</strong> A real <code>0.1.0-preview.25</code> release — built by CI (<code>build-image.yml</code>), signed offline by the maintainer with the real production key (<a href="./docs/adrs/0006-production-signing-key-custody.html">ADR-0006</a>, the assistant never handled it), staged/tried/committed on both the base-OS and appliance layers of the real qualification device. This is the artifact/import systemd paths&#39; and <code>sovereign-conversation.service</code>&#39;s real <code>DynamicUser</code> sandbox&#39;s first genuine exercise on real hardware — see the <a href="./docs/research/searxng-and-llamacpp-signed-release-hardware-qualification-report.html">full report</a>. Found and fixed three real defects along the way, none caught by any unit test: <code>build-image.yml</code> never passed SearXNG&#39;s required flags to <code>create-update-release.py</code> (would have failed CI outright); the AB image&#39;s own unit-enable script never enabled llama.cpp&#39;s, SearXNG&#39;s, or the Conversation Service&#39;s units (present on disk, <code>disabled</code>); and <code>sovereign-conversation.service</code> crash-looped on its first-ever real sandboxed start, since <code>ReadWritePaths=</code> — unlike <code>StateDirectory=</code> — doesn&#39;t auto-create a missing target, and neither of its two paths existed on a freshly-committed device. All three are merged to <code>main</code>; a device built fresh from current <code>main</code> needs none of the manual workarounds this pass used mid-flight.</p><p><strong>Compose-template validation is now extended to all three images.</strong><code>validate_appliance_configuration</code> previously rendered and ran <code>docker compose config --quiet</code> against Pi-hole&#39;s Compose template only; a malformed <code>llama/compose.yaml.in</code> or <code>searxng/compose.yaml.in</code> would have passed release validation silently and only failed later, at real Compose-up time on a device. Generalized into the same <code>COMPOSE_TEMPLATES</code> data-driven loop shape <code>IMAGE_COMPONENTS</code> already established, handling llama&#39;s second (<code>@LLAMA_MODEL_FILENAME@</code>, substituted at deploy time, not release-validation time) placeholder and SearXNG&#39;s <code>SEARXNG_SECRET</code> env-var reference along the way. Verified against real <code>docker</code> (not the fake stub the rest of this suite uses) that all three real templates pass and a structurally broken one is rejected (<code>tests/test_appliance_compose_validation.py</code>).</p><p><strong>Conversation Service:</strong> implemented — <code>sovereign_conversation.py</code> (RFC-0003/0004&#39;s bounded propose→execute→narrate loop: max 3 rounds per turn, max 3 capability proposals per round, per-capability invocation budgets enforced, capability results re-enter context as plain untrusted <code>tool</code>-role messages) sits behind a thin loopback-only HTTP wrapper, <code>bin/sovereign-conversation</code> (<code>GET /api/v1/conversation/health</code>, <code>POST /api/v1/conversation/message</code>), running as <code>sovereign-conversation.service</code> (<code>DynamicUser=yes</code>, hardened, not yet auto-enabled — see below). Deliberately out of scope for this pass: streaming (the selected llama.cpp adapter can&#39;t parse tool calls from a streamed response, so every round is single-shot), a working confirmation pause/resume flow (capabilities requiring confirmation are detected and refused with a clear error — nothing registered needs one yet), and conversation storage (stateless; the caller supplies full history per call). 26 unit/HTTP-layer tests cover the turn loop and the live service, and it has been smoke-tested end to end on the real device — real inference (llama.cpp + Qwen2.5-3B-Instruct), all three registered capabilities proposed/executed/narrated correctly (including a model-chosen structured argument for <code>pihole.summary</code>), a compliant audit trail, and correct error handling. See the <a href="./docs/research/conversation-service-smoke-test-report.html">smoke test report</a>.</p><p>Wiring in the Pi-hole capabilities surfaced a real production gap: <code>pihole-admin-password</code> was root-only (<code>0600</code>), which an unprivileged <code>DynamicUser</code> service could never read. Fixed by mirroring console-auth&#39;s own established pattern — a new <code>sovereign-pihole-secrets</code> sysusers.d group, <code>start-pihole</code>/<code>sovereign-pihole-password</code> now set the secrets directory to <code>0710</code> and the password file to <code>0640</code> group-readable (<code>chown root:sovereign-pihole-secrets</code>).</p><p><strong>Authentication:</strong> wired, reusing console-auth&#39;s own session boundary rather than a second one (RFC-0002/ADR-0007). console-auth gained <code>GET /api/v1/auth/verify-mutating</code> — like the existing <code>/api/v1/auth/verify</code> used to gate <code>/dns/</code> via Nginx <code>auth_request</code>, but also checking the CSRF token, since a conversation turn does real work directly (inference, capability execution) rather than navigating to a panel with its own separate login. <code>bin/sovereign-conversation</code> delegates to it on every <code>POST /message</code>, forwarding the caller&#39;s <code>Cookie</code> and <code>X-CSRF-Token</code> headers and translating 401/403/unreachable into its own JSON errors; <code>GET /health</code> stays open, matching <code>/api/v1/health</code>&#39;s own boundary (liveness only, nothing household-specific). Nginx now proxies both routes onto the LAN-facing surface — <code>/message</code> with a 180s read timeout, since a turn can run multiple real inference calls across propose/execute/narrate rounds, well past the 5s every other API location here uses. Smoke-tested against real hardware: all three auth outcomes (no session, valid session with a missing/wrong CSRF token, valid session with the correct one) verified over real HTTP, plus one full authenticated turn reaching real inference and executing <code>system.health</code> — see the <a href="./docs/research/conversation-service-authentication-smoke-test-report.html">report</a>.</p><p><strong>llama-server deployment and auto-enabling:</strong> done, per <a href="./docs/adrs/0014-llama-server-deployment-and-model-provisioning.html">ADR-0014</a>. The llama.cpp runner image is embedded in the base image and every release exactly the way Pi-hole&#39;s is (<code>llama-image.env</code>, a real <code>skopeo</code>-fetched digest, the same three-stage artifact/import/server systemd shape). ADR-0013&#39;s selected model (Qwen2.5-3B-Instruct-Q4_K_M) is deliberately <strong>not</strong> embedded — it does not fit the real device&#39;s A/B system partition&#39;s size budget (confirmed this session: ~2.0GB free, the model alone is ~2GB) — <code>start-llama-server</code> downloads it into <code>/data/sovereign/models/</code> on first start instead, and re-verifies its SHA-256 digest on every start after that, not just once. <code>sovereign-conversation.service</code> gets a soft <code>After=</code> (not <code>Requires=</code>) on the new <code>sovereign-llama-server.service</code>, so a still-downloading or failed model load falls into the Conversation Service&#39;s existing, already-tested <code>PROVIDER_UNAVAILABLE</code> degraded response. All four units (<code>sovereign-llama-artifact</code>, <code>sovereign-llama-import</code>, <code>sovereign-llama-server</code>, <code>sovereign-conversation</code>) are now in <code>customize90-sovereign</code>&#39;s enable-units list — the actual gap this milestone was blocked on.</p><p>Known, disclosed tradeoff: a fresh install&#39;s first boot needs real internet access and a multi-minute ~2GB download before conversation works at all — a real regression from Pi-hole&#39;s fully-offline-after-imaging posture, not hidden in the ADR.</p><p><strong>Deployment path qualified on real hardware.</strong> <code>verify-llama-artifact</code>, <code>import-llama-image</code>, and <code>start-llama-server</code> all ran for real against a genuine <code>skopeo</code>-fetched artifact of the exact pinned digest (not a full <code>rpi-image-gen</code> build, which stays out of scope for a smoke pass — see the report&#39;s Limitations) — real checksum/tar-content verification, real <code>docker load</code>+tag+platform check, real ~2GB model download, and a real completion request whose <code>system_fingerprint</code> matched the exact pinned upstream revision. Idempotency (a second run skips the download) and the core trust-boundary claim — a corrupted model file is detected and transparently re-downloaded, not silently trusted — were both confirmed live, not just read from the script. Full writeup: <a href="./docs/research/llama-server-deployment-qualification-report.html">llama-server-deployment-qualification-report.md</a>.</p><p><strong>Runner and model benchmarking is concluded.</strong><code>scripts/benchmark-inference-runner.py</code> (backed by <code>sovereign_inference.py</code>, RFC-0002&#39;s Inference Provider Adapter contract against both llama.cpp and Ollama) ran six real hardware passes across two runners, two model sizes, and two corpora — including finding and fixing a real bug (streaming silently dropped capability proposals), confirming genuine thermal throttling via <code>vcgencmd get_throttled</code> for the first time in this project&#39;s history, and building a 28-item evaluation corpus after the initial 5-item one hit a ceiling effect. Full narrative and data in the <a href="./docs/research/llamacpp-qwen2.5-3b-benchmark-report.html">llama.cpp 3B</a>, <a href="./docs/research/llamacpp-qwen2.5-7b-benchmark-report.html">llama.cpp 7B</a>, <a href="./docs/research/ollama-qwen2.5-3b-benchmark-report.html">Ollama 3B</a>, <a href="./docs/research/v1-corpus-benchmark-report.html">v1 corpus</a>, and <a href="./docs/research/dns-latency-during-generation-qualification-report.html">DNS-latency-during-generation</a> reports. That evidence became two accepted decisions: <a href="./docs/adrs/0012-local-inference-resource-and-dns-latency-budgets.html">ADR-0012</a> (80°C thermal budget, 40%-of-RAM memory ceiling, 50ms DNS-latency budget) and <a href="./docs/adrs/0013-initial-inference-runner-and-model-selection.html">ADR-0013</a> (<strong>llama.cpp + Qwen2.5-3B-Instruct</strong> selected — better v1-corpus accuracy than Ollama, no cold-start penalty, and Qwen2.5-7B excluded outright on the memory budget). Two non-blocking validation gaps remain open per ADR-0013&#39;s Required Follow-up (a realistic intermittent-use thermal pass; broader DNS-latency-during-generation coverage) but do not block moving on.</p><p><strong>Console Chat is now wired to the real Conversation Service.</strong> The Chat nav page (<code>console/index.html</code>, <code>console/assets/console.js</code>/<code>console.css</code>) is no longer a static design preview: the composer posts to <code>/api/v1/conversation/message</code> with the caller&#39;s session cookie and CSRF token (reusing the same <code>csrfToken</code> console-auth&#39;s own sign-in flow already maintains), renders the returned text and <code>capability_events</code> as chat bubbles and receipts, and shows <code>/api/v1/conversation/health</code> in the trust strip. Sending is gated on a signed-in Console session — the composer stays disabled with a &quot;Sign in to chat with Sovereign&quot; prompt until then, matching the same session boundary the update-install flow uses. Client-side history sent back on each turn is capped at 20 messages to stay under <code>/message</code>&#39;s 64KiB request-body ceiling. Activity remains a static design preview; Home Assistant&#39;s page now carries real, Console-wired settings for its own read-only integration (Milestone 5) alongside its still-preview mutating-control mockup. Implemented, unit-tested (<code>tests/test_console.py</code>), and <strong>hardware-qualified</strong> — see the <a href="./docs/research/web-search-and-confirmation-flow-hardware-qualification-report.html">web.search/confirmation flow hardware qualification report</a> for a real browser-authenticated Chat pass driven by the project owner.</p><p><strong>Remaining:</strong> nothing — a real <code>build-image.yml</code> base-OS build has now exercised the llama-server (and SearXNG) deployment path through the actual build pipeline end to end, not just reproduced by hand (see the <a href="./docs/research/searxng-and-llamacpp-signed-release-hardware-qualification-report.html">signed-release qualification report</a> above). <code>web.search</code>/<code>web.fetch</code> itself — deployment, capability implementation, confirmation/policy wiring, Console UI, and hardware qualification — is done, and RFC-0017 is now Accepted (see above).</p><p><strong>Depends on:</strong> Stable appliance update boundary</p><p><strong>User outcome:</strong> Ask Sovereign local questions, inspect system and Pi-hole status, and explicitly use privacy-transparent, self-hosted web-search tooling.</p><p>Milestone 01.2 will deliver:</p><ul><li>a Sovereign-owned conversation experience;</li><li>provider-neutral local inference and model-management contracts;</li><li>a Raspberry Pi 5 benchmark of llama.cpp and Ollama;</li><li>a typed capability registry and deterministic executor;</li><li><code>system.health</code> and read-only Pi-hole capabilities;</li><li>opt-in <code>web.search</code> through a locally operated SearXNG instance;</li><li>restricted <code>web.fetch</code>, citations, privacy indicators, and audit events; and</li><li>real-hardware qualification within DNS-latency, memory, power, and thermal budgets.</li></ul><h3 id="_5-home-automation-integration" tabindex="-1">5. Home Automation Integration <a class="header-anchor" href="#_5-home-automation-integration" aria-label="Permalink to &quot;5. Home Automation Integration&quot;">​</a></h3><p><strong>Status:</strong> 🟡 In progress — both slices implemented, unit-tested, and manually verified in Console (including the second slice&#39;s control toggle/picker); real-hardware qualification of either slice blocked on an external dependency (see below)</p><p><strong>Depends on:</strong> Qualified capability executor (satisfied — see Milestone 4&#39;s real-hardware qualification of the confirmation/policy/audit machinery via <code>web.search</code>/<code>web.fetch</code>)</p><p><strong>User outcome:</strong> Ask about and safely control allowlisted home entities through the same Sovereign conversation boundary.</p><p>The first slice is read-only Home Assistant entity discovery, state, and history. Later slices may propose allowlisted actions, but deterministic policy outside the model must authorize them and require confirmation according to risk. The model never receives unrestricted Home Assistant, shell, Docker, or network access.</p><p><a href="./docs/rfcs/0018-home-assistant-read-only-capability-mapping.html">RFC-0018</a> (Accepted 2026-08-21) maps the first slice&#39;s two capabilities (<code>home_assistant.list_entities</code>, <code>home_assistant.get_history</code>) against RFC-0003&#39;s contract, reusing RFC-0017&#39;s confirmation wire format unchanged. It classifies Home Assistant traffic as <code>external</code> (a separate household-owned host, not device-local) — a disclosed, deliberately conservative reading of RFC-0003&#39;s existing <code>local</code>/<code>external</code> axis rather than a unilateral amendment to it — fixes the entity allowlist mechanism (checked before confirmation, not merely before execution), and fixes where the connection&#39;s long-lived access token is stored, mirroring <code>pihole-admin-password</code>&#39;s existing precedent.</p><p><strong>Implemented and Console-wired</strong> (<code>sovereign_homeassistant.py</code>, <code>bin/sovereign-conversation</code>&#39;s three new endpoints, and Console&#39;s Home Assistant page): the capability executor generalization (<code>policy_key</code>/<code>policy_check</code>, so enabling web search no longer silently enables Home Assistant too), config/credential storage, and a real settings UI (connection fields, entity-allowlist picker) — manually verified end-to-end in a browser against a stub backend. Unlike Pi-hole/SearXNG/llama.cpp, Sovereign does not deploy or manage Home Assistant itself — <strong>real-hardware qualification is blocked</strong>, not merely pending: confirmed with the project owner that no Home Assistant instance currently exists on the household network, so this milestone has no target to qualify against yet. This stays an open item until one does.</p><p><a href="./docs/rfcs/0019-home-assistant-allowlisted-action-capability-mapping.html">RFC-0019</a> (Accepted 2026-08-21) maps the second slice&#39;s one capability (<code>home_assistant.set_entity_state</code>), answering RFC-0003/RFC-0004&#39;s shared, explicitly-deferred question of what mutating-capability confirmation UX should look like now that a real mutating capability exists to design one around. Deliberately scoped to <code>light</code>/<code>switch</code> domains only (binary, fully reversible, no numeric range or safety implication) — every other domain (locks, climate, covers, cameras) is named as out of scope for a future RFC, the concrete answer to &quot;confirmation according to risk&quot;: narrower scope, not a new confirmation tier RFC-0003&#39;s table doesn&#39;t have. Introduces a second, independent allowlist and policy toggle (<code>controllable_entities</code>/ <code>home_assistant_control_enabled</code>) so enabling read access never silently enables control, mirroring RFC-0018&#39;s own web-search/Home-Assistant separation one level deeper. Review before acceptance found a real gap: domain scope was claimed enforced at three points but only one (config write) was actually designed — closed by adding two independent domain re-checks, since Home Assistant&#39;s <code>climate</code> domain has real <code>turn_on</code>/<code>turn_off</code> services that wouldn&#39;t have failed safely by accident if a non-light/switch entity ever reached the service call.</p><p><strong>Implemented</strong> (<code>sovereign_homeassistant.py</code>&#39;s <code>set_entity_state</code>, the extended <code>home-assistant.json</code>/<code>POST /api/v1/conversation/home-assistant</code> config surface): idempotent no-ops (a proposal matching current state never contacts Home Assistant), and success verified against the real service-call response rather than trusting a 200 status alone. Extending the config endpoint&#39;s required fields would have silently broken Console&#39;s already-shipped read-only &quot;Save connection&quot; button — fixed by having it load, retain, and resend the two new control fields even before any UI existed to edit them.</p><p><strong>Console-wired</strong>: an &quot;Allow control&quot; toggle independent of the existing &quot;Allow Home Assistant&quot; toggle, and a per-entity &quot;Control&quot; checkbox next to each allowlisted entity&#39;s existing &quot;Read&quot; checkbox — offered only for <code>light</code>/<code>switch</code>-domain entities, disabled until Read is checked for that entity, and cascaded off if Read is later unchecked (client-side mirror of the same subset invariant <code>write_config()</code> enforces server-side). Manually verified end-to-end in a browser against a stub backend: sign in, save a connection, enable both toggles, load entities, confirm Control is offered only for light/switch domains, check Read+Control on two entities, save, reload, and confirm both the toggle and per-entity grants persisted. Real-hardware qualification depends on the same unresolved external dependency (no Home Assistant instance yet) named above.</p><h3 id="_6-full-base-os-updates" tabindex="-1">6. Full Base-OS Updates <a class="header-anchor" href="#_6-full-base-os-updates" aria-label="Permalink to &quot;6. Full Base-OS Updates&quot;">​</a></h3><p><strong>Status:</strong> ✅ Complete — every RFC-0016 Acceptance Criteria item is now hardware-qualified, including the two hardest ones: a second base-OS update with no reflash, and a genuine reflash-then-restore recovery round trip. A few small implementation-detail questions remain open in RFC-0016&#39;s own Unresolved Questions (CLI/API shape polish, whether a base-OS and appliance update could ever share one transaction), none of them blocking — <a href="./docs/rfcs/0016-full-base-os-updates.html">RFC-0016</a> (accepted 2026-08-01): A/B root on Raspberry Pi&#39;s native <code>tryboot</code> mechanism, reusing RFC-0014&#39;s signed/staged/health-gated/rollback machinery rather than adopting a third-party OTA framework. Existing single-root devices (including this project&#39;s own qualification hardware) migrate via a one-time reflash, then receive base-OS updates like any new device from that point forward. The <code>tryboot</code>/trial/commit/recovery cycle, release tooling, <code>recover</code>/<code>prune</code> transaction integration, and CI release-candidate wiring are all hardware- or live-verified.</p><p>The qualification device — already migrated to A/B on 2026-08-02 — received a genuine <strong>second</strong> base-OS update on 2026-08-06 with no further reflash: staged, trialed, health-gated, and committed, confirmed persistent across an ordinary reboot. The Console base-OS panel — a read-only <code>/api/v1/update/base-os-status</code> route and matching panel, deployed the same day onto the device&#39;s separately-stale Console — was then confirmed genuinely serving that real transaction data through the real nginx proxy. See the <a href="./docs/research/second-base-os-update-hardware-qualification-report.html">second base-OS update qualification report</a> for both. That work found four real already-flashed-device compatibility gaps — a pre-fix <code>sovereign-update</code> binary rejecting modern manifests, a <code>&quot;proof&quot;</code>/<code>&quot;preview&quot;</code> semver-ordering collision that permanently blocked such devices from real <code>preview.N</code> base-OS releases, a stale-binary transaction missing a field the recovery logic needs (causing a healthy trial to be falsely flagged as interrupted), and <code>installed_base_os_version</code> being a hardcoded build-time placeholder that never reflected the real installed version. None of the four blocked a freshly-flashed device. As of 2026-08-07, all four are resolved: the ordering collision and the placeholder both got real code fixes (<code>compare_versions</code>&#39;s new <code>PRERELEASE_CHANNEL_ORDER</code> table; <code>pre-image.sh</code> now templates from <code>$SOVEREIGN_VERSION</code>), each with new test coverage; the other two needed no separate fix, since <code>main</code> already contained their fixes — the qualification device just hadn&#39;t received them yet.</p><p>The external recovery-image path — the last named-but-undesigned requirement — is decided and hardware-qualified via <a href="./docs/adrs/0011-external-recovery-image-path.html">ADR-0011</a>: the existing distributable image, reflashed via Raspberry Pi Imager, is the recovery vehicle (no dedicated recovery-only OS), and the previously-untested &quot;reflash, then restore my data&quot; gap is closed. The qualification device was genuinely reflashed (wiping it entirely, via a new CI artifact for the actual flashable A/B disk image, since none existed before) and a pre-reflash backup restored onto it through the existing, unmodified <code>backup</code>/<code>restore</code> commands — every persisted file (Pi-hole state, admin-password secret) independently verified byte-for-byte, the restored device&#39;s DNS service confirmed genuinely working, and zero code changes needed. See the <a href="./docs/research/external-recovery-backup-restore-qualification-report.html">external recovery backup/restore qualification report</a>.</p><p><strong>Depends on:</strong> Stable appliance updater and persistent partition contract</p><p><strong>User outcome:</strong> Update Debian, kernel, firmware, Docker, and early system services without reflashing.</p><p>The current updater covers versioned Sovereign appliance releases; it does not make base-OS package transactions atomic. The long-term milestone must select and qualify an A/B root-filesystem or equivalent immutable deployment design with:</p><ul><li>persistent DATA independent of either system slot;</li><li>atomic boot-slot selection;</li><li>boot and health confirmation;</li><li>automatic fallback to the previous system;</li><li>signed system artifacts; and</li><li>an external recovery-image path.</li></ul><p>This milestone closes the remaining “flash once” gap.</p><h2 id="progress-summary" tabindex="-1">Progress Summary <a class="header-anchor" href="#progress-summary" aria-label="Permalink to &quot;Progress Summary&quot;">​</a></h2><ul><li>✅ Concept paper and master plan</li><li>✅ Phase 01 appliance architecture decision</li><li>✅ <code>rpi-image-gen</code> assessment, proof build, and automated ARM64 image pipeline</li><li>✅ Flashable Raspberry Pi 5 image exercised on hardware</li><li>✅ Docker-based Pi-hole, <code>/dns/*</code> routing, and persistent DATA</li><li>✅ First-login credential-change and optional SSH-key flow</li><li>✅ Sovereign Console read-only health page qualified on Raspberry Pi 5</li><li>✅ Signed update transaction, interruption recovery, rollback, and persistence demonstrated on Raspberry Pi 5</li><li>✅ Fully versioned appliance-release qualification (preview.11 to preview.12), including readiness hardening</li><li>✅ Persistent restore automation, retention, and production signing operations</li><li>✅ Update discovery and Sovereign Console update controls</li><li>✅ Local inference benchmark — six real Raspberry Pi 5 passes across two runners, two model sizes, and two corpora, closed by ADR-0012 (thermal, memory, and DNS-latency budgets) and ADR-0013 (runner and model selection)</li><li>✅ Conversation and capability RFCs — RFC-0002, RFC-0003, RFC-0004, and RFC-0006 all Accepted, with the Conversation Service and its <code>system.health</code> and Pi-hole capabilities implemented and hardware-qualified</li><li>✅ SearXNG-backed web-search capability — implemented, unit-tested, fully wired into Console&#39;s Chat UI including the settings toggle, and hardware-qualified twice: a real smoke-test end-to-end pass (RFC-0017, Accepted), and a real signed-release qualification (artifact/import systemd paths, the real hardened sandbox) closing PR #17&#39;s last open checklist item</li><li>🟡 Home Assistant capability integration — read-only entity/history mapping (RFC-0018) and allowlisted-action mapping (RFC-0019, <code>light</code>/<code>switch</code> only) both implemented and Console-wired; real-hardware qualification of either blocked on no Home Assistant instance existing on the household network yet</li><li>✅ A/B full base-OS updates (RFC-0016): every Acceptance Criteria item hardware-qualified, including a second base-OS update with no reflash, the Console panel against a live transaction, and a genuine reflash-then-restore recovery round trip (ADR-0011); four real already-flashed-device defects found and fixed</li></ul><hr><h2 id="phases" tabindex="-1">Phases <a class="header-anchor" href="#phases" aria-label="Permalink to &quot;Phases&quot;">​</a></h2><ul><li><a href="./docs/roadmap/00-master-plan.html">00 Master Plan</a></li><li><a href="./docs/roadmap/01-preview-poc.html">01 Flashable Pi-hole Image POC</a></li><li><a href="./docs/roadmap/01-console-foundation.html">Console Foundation</a></li><li><a href="./docs/roadmap/01-1-update-foundation.html">01.1 Appliance Update Foundation</a></li><li><a href="./docs/roadmap/01-2-local-conversation-capabilities.html">01.2 Local Conversation and Capabilities</a></li></ul><h2 id="project-documentation" tabindex="-1">Project Documentation <a class="header-anchor" href="#project-documentation" aria-label="Permalink to &quot;Project Documentation&quot;">​</a></h2><ul><li><a href="./docs/README.html">Documentation index</a></li><li><a href="./docs/product/target-user.html">Initial target user</a></li><li><a href="./docs/product/core-use-cases.html">Core preview use cases</a></li><li><a href="./docs/product/preview-scope.html">Preview scope and non-goals</a></li><li><a href="./docs/architecture/system-overview.html">System overview</a></li><li><a href="./docs/security/threat-model.html">Preview threat model</a></li><li><a href="./docs/adrs/0001-phase-01-appliance-architecture.html">ADR-0001: Phase 01 appliance architecture</a></li><li><a href="./docs/rfcs/0010-raspberry-pi-image-deployment.html">RFC-0010: Raspberry Pi image deployment</a></li><li><a href="./docs/operations/image-release-checklist.html">Image release checklist</a></li><li><a href="./docs/adrs/0002-install-images-and-update-artifacts.html">ADR-0002: Installation images and update artifacts</a></li><li><a href="./docs/adrs/0004-provider-neutral-assistant-and-web-search.html">ADR-0004: Provider-neutral assistant and web search</a></li><li><a href="./docs/adrs/0005-sovereign-console-and-health-boundary.html">ADR-0005: Sovereign Console namespace and health boundary</a></li><li><a href="./docs/rfcs/0014-appliance-update-system.html">RFC-0014: Appliance update system</a></li><li><a href="./docs/rfcs/0016-full-base-os-updates.html">RFC-0016: Full base-OS updates (A/B root filesystem)</a></li><li><a href="./docs/research/preview-12-appliance-update-qualification-report.html">Preview.12 appliance update qualification report</a></li></ul>',83)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
